// Offline icons: only the Solar icons we use are bundled, nothing is fetched from the Iconify API.
import type { IconProps } from '@iconify/react';

import { Icon, addCollection } from '@iconify/react';

import Box from '@mui/material/Box';
import type { SxProps, Theme } from '@mui/material/styles';

// Generated by scripts/icons-subset.mjs (runs before dev/build) from the solar:* names used in src/.
import subset from './icons-subset.json';

addCollection(subset as Parameters<typeof addCollection>[0]);

export type IconifyName = `solar:${string}`;

type Props = Omit<IconProps, 'icon'> & { icon: IconifyName | string; width?: number; sx?: SxProps<Theme> };

export function Iconify({ icon, width = 20, sx, ...other }: Props) {
  return (
    <Box
      component={Icon}
      icon={icon}
      sx={{ width, height: width, flexShrink: 0, display: 'inline-flex', ...sx } as SxProps<Theme>}
      {...(other as object)}
    />
  );
}
